(()=>{'use strict';const dialog=document.getElementById('take-along-dialog');if(!dialog)return;let previous=null;const close=()=>dialog.close();document.querySelectorAll('[data-open-qr]').forEach(button=>button.addEventListener('click',()=>{previous=button;dialog.showModal();document.body.classList.add('qr-open');dialog.querySelector('[data-close-qr]').focus()}));dialog.querySelector('[data-close-qr]').addEventListener('click',close);dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});dialog.addEventListener('close',()=>{document.body.classList.remove('qr-open');previous?.focus()});})();